static bool ts_lex_keywords(TSLexer *lexer, TSStateId state) {
  START_LEXER();
  eof = lexer->eof(lexer);
  switch (state) {
    case 0:
      if (set_contains(sym_identifier_character_set_1, 758, lookahead)) ADVANCE(1);
      END_STATE();
    case 1:
      ACCEPT_TOKEN(aux_sym_binding_reference_token1);
      if (set_contains(sym_identifier_character_set_2, 759, lookahead)) ADVANCE(1);
      END_STATE();
    default:
      return false;
  }
}

